const createReplaceStream = (search, replacement, maxBufferSize = 16384) => {
  let buffer = '';

  return new Transform({
    transform(chunk, encoding, callback) {
      buffer += chunk.toString();

      while (buffer.length >= maxBufferSize) {
        const lastIndex = buffer.lastIndexOf(replacement);
        if (lastIndex === -1 || lastIndex < maxBufferSize) {
          const chunkToProcess = buffer.slice(0, maxBufferSize);
          buffer = buffer.slice(maxBufferSize);
          this.push(chunkToProcess.replace(search, replacement));
        } else {
          const chunkToProcess = buffer.slice(0, lastIndex + replacement.length);
          buffer = buffer.slice(lastIndex + replacement.length);
          this.push(chunkToProcess.replace(search, replacement));
        }
      }

      callback();
    },
    flush(callback) {
      if (buffer) {
        this.push(buffer.replace(search, replacement));
      }
      callback();
    },
  });
};
```
